import React from "react";
import "../App.css";

const Book = () => {
  const books = [
    {
      id: 1,
      img: ".../public/image1.jpg",
      bookName: "The Witch",
      Author: "Freida McFadden",
      price: "$48",
    },
    {
      id: 2,
      img: ".../public/image2.jpg",
      bookName: "The Answer Is No: A Short Story",
      Author: "Fredrik Backman",
      price: "$4",
    },
    {
      id: 3,
      img: ".../public/image3.jpg",
      bookName: "Fake it 'til",
      Author: "Laura Carten",
      price: "$8",
    },
  ];
  return (
    <div>
      {Book.map((item) => (
        <div className="card" key={item.id}>
          <img src={item.img} alt={item.bookName} />
          <h3>{item.bookName}</h3>
          <p>{item.Author}</p>
          <p>{item.price}</p>
          <button onClick={() => alert(`Item added ${item.bookName}, Price: `)}></button>
        </div>
      ))}
    </div>
  );
};

export default Book;
